const money = (value: number | undefined) =>
  value === undefined || Number.isNaN(value)
    ? '—'
    : new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(value);
const compactMoney = (value: number | undefined) =>
  value === undefined || Number.isNaN(value)
    ? '—'
    : value >= 10000000
      ? `₹${(value / 10000000).toFixed(1)}Cr`
      : value >= 100000
        ? `₹${(value / 100000).toFixed(1)}L`
        : money(value);
const dateLabel = (value?: string) => {
  if (!value) return 'Not available';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }).format(date);
};
const timeLabel = (value?: string) => {
  if (!value) return '—';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('en-IN', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }).format(date);
};

function StatusBadge({ status }: { status: string }) {
  const tone = status === 'critical' || status === 'gap' ? 'danger' : status === 'elevated' || status === 'attention' ? 'warn' : status === 'controlled' || status === 'compliant' ? 'good' : 'quiet';
  return <span data-testid={`status-${status}`} className={`rr-badge rr-${tone}`}>{status.replace('-', ' ')}</span>;
}

function Skeleton({ className = '' }: { className?: string }) {
  return <div className={`animate-pulse rounded-md bg-[hsl(var(--muted))] ${className}`} aria-label="Loading" data-testid="loading-skeleton" />;
}

function QueryState({ isLoading, isError, isEmpty, onRetry, children, emptyLabel = 'No records to show yet.' }: { isLoading?: boolean; isError?: boolean; isEmpty?: boolean; onRetry?: () => void; children: ReactNode; emptyLabel?: string }) {
  if (isLoading) return <div className="space-y-3" data-testid="state-loading"><Skeleton className="h-16 w-full" /><Skeleton className="h-16 w-11/12" /><Skeleton className="h-16 w-10/12" /></div>;
  if (isError) return <div className="rr-state" data-testid="state-error"><CircleAlert size={20} /><div><strong>Could not load this view</strong><p>RiskRupee could not reach the quantification service.</p></div>{onRetry && <button type="button" className="rr-button rr-button-quiet ml-auto" onClick={onRetry} data-testid="button-retry">Retry</button>}</div>;
  if (isEmpty) return <div className="rr-state" data-testid="state-empty"><Database size={20} /><div><strong>{emptyLabel}</strong><p>Connect a source or add your first record to begin quantifying exposure.</p></div></div>;
  return <>{children}</>;
}

